-- SELECT only. Run before dry-run/apply (also the before/after comparison for postcheck). Aggregates and hashes; no row text.
-- 읽기 전용 역할(표 소유자 아님)에서 돈다: information_schema 대신 pg_catalog만 읽는다.
-- 적용 전 기대: 앞 단계 둘(20261024140000, 20261024210000) 적용됨, 개인 통화 표·새 함수·새 칸·새 트리거 없음, 트리거 함수가 앞 단계 본문,
--   authenticated는 넣기·지우기·source 쓰기 없음, anon·PUBLIC 표 권한 없음, 업무 표(app_feed_items)의 줄 수와 권한·정책 해시는 기록만 하고 사후 확인에서 같은 값이어야 한다.
-- expect: feed items rows = 기록
-- expect: feed table grants policies hash = 기록
select 'new migration absent' as item,case when not exists(select 1 from supabase_migrations.schema_migrations where version='20261025200000') then '예' else '아니오' end as value
union all select 'previous steps applied (feed table, guard)',case when (select count(*) from supabase_migrations.schema_migrations where version='20261024140000' and name='call_tg_feed')=1 and (select count(*) from supabase_migrations.schema_migrations where version='20261024210000' and name='feed_item_guard_public')=1 and to_regclass('public.app_feed_items') is not null then '예' else '아니오' end
union all select 'personal table, new functions and new triggers absent',case when to_regclass('public.app_call_personal') is null and to_regprocedure('public.app_call_move(uuid,text)') is null and to_regprocedure('public.app_call_work_info(uuid,text,text,uuid)') is null and to_regprocedure('private.app_call_ref_guard()') is null and to_regprocedure('private.app_call_personal_guard()') is null and not exists(select 1 from pg_trigger where tgrelid=to_regclass('public.app_feed_items') and tgname='app_feed_items_call_ref_guard') then '예' else '아니오' end
union all select 'new columns absent',case when not exists(select 1 from pg_attribute where attrelid=to_regclass('public.app_feed_items') and not attisdropped and attname in('moved_at','refilled_at')) then '예' else '아니오' end
union all select 'source check has only call and telegram',case when exists(select 1 from pg_constraint where conrelid=to_regclass('public.app_feed_items') and conname='app_feed_items_source_check' and pg_get_constraintdef(oid) not like '%call_personal%') then '예' else '아니오' end
union all select 'guard invoker, empty search_path, no private call (previous body)',case when exists(select 1 from pg_proc where oid=to_regprocedure('private.app_feed_item_guard()') and not prosecdef and proconfig=array['search_path=""'] and prosrc not like '%private.%' and prosrc like '%FEED_LINK_SCOPE%') then '예' else '아니오' end
union all select 'one guard trigger on feed items',case when (select count(*) from pg_trigger where tgrelid=to_regclass('public.app_feed_items') and not tgisinternal)=1 then '예' else '아니오' end
union all select 'owner check function exists (definer)',case when exists(select 1 from pg_proc where oid=to_regprocedure('private.app_is_workspace_owner(uuid)') and prosecdef) then '예' else '아니오' end
union all select 'authenticated cannot insert delete or write source',case when not has_table_privilege('authenticated','public.app_feed_items','insert') and not has_table_privilege('authenticated','public.app_feed_items','delete') and not has_column_privilege('authenticated','public.app_feed_items','source','update') then '예' else '아니오' end
union all select 'service_role can read the three duplicate-check columns',case when has_column_privilege('service_role','public.app_feed_items','workspace_id','select') and has_column_privilege('service_role','public.app_feed_items','source','select') and has_column_privilege('service_role','public.app_feed_items','source_ref','select') then '예' else '아니오' end
union all select 'no anon or PUBLIC table privilege, RLS on, one policy',case when exists(select 1 from pg_class where oid=to_regclass('public.app_feed_items') and relrowsecurity and not relforcerowsecurity and coalesce(relacl::text,'')!~'(^|[{,])(anon)?=') and (select count(*) from pg_policy where polrelid=to_regclass('public.app_feed_items'))=1 then '예' else '아니오' end
union all select 'feed items rows',(select count(*)::text from public.app_feed_items)
union all select 'feed table grants policies hash',md5(coalesce((select string_agg(c.relname||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_days'))),'')
  ||coalesce((select string_agg(a.attname::text||':'||a.attacl::text,',' order by a.attname) from pg_attribute a where a.attrelid=to_regclass('public.app_feed_items') and a.attnum>0 and not a.attisdropped and a.attacl is not null),'')
  ||coalesce((select string_agg(p.polname::text||p.polcmd::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polname) from pg_policy p where p.polrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_days'))),''));
